export const meta = {
  name: 'study-and-ideate-swiftmandarin',
  description: 'Map every subsystem of SwiftMandarin in parallel, then generate step-change improvement ideas from 10 expert lenses',
  phases: [
    { title: 'Understand', detail: '10 parallel subsystem readers' },
    { title: 'Ideate', detail: '10 expert-lens feature generators' },
    { title: 'Synthesize', detail: 'dedupe, rank, completeness critic' },
  ],
}

const ROOT = '/Users/rogerlin/XCode-Projects/SwiftMandarinShortcuts'

const UNDERSTAND_SCHEMA = {
  type: 'object',
  properties: {
    subsystem: { type: 'string' },
    summary: { type: 'string', description: 'What this subsystem does, <=150 words' },
    keyTypes: { type: 'array', items: { type: 'object', properties: { name: { type: 'string' }, role: { type: 'string' } }, required: ['name','role'] } },
    dataFlow: { type: 'string', description: 'How data moves through it, <=100 words' },
    persistence: { type: 'string', description: 'How/where state is persisted, <=60 words' },
    uxDescription: { type: 'string', description: 'What the user sees and does in these views, <=150 words. Empty if no UI.' },
    strengths: { type: 'array', items: { type: 'string' } },
    weaknesses: { type: 'array', items: { type: 'string' }, description: 'Tech debt, UX pain points, missing capabilities, code smells' },
    opportunities: { type: 'array', items: { type: 'string' }, description: 'Concrete improvement ideas noticed while reading' },
  },
  required: ['subsystem','summary','keyTypes','dataFlow','persistence','uxDescription','strengths','weaknesses','opportunities'],
}

const SUBSYSTEMS = [
  { key: 'app-shell', files: 'SwiftMandarin/SwiftMandarinApp.swift, SwiftMandarin/ContentView.swift, SwiftMandarin/AppConfig.swift, SwiftMandarin/Models/AppRouteStore.swift, SwiftMandarin/Views/MoreView.swift, SwiftMandarin/Views/MacOSSettingsView.swift, SwiftMandarin/Models/AppPreferences.swift, SwiftMandarin/Models/LocalizationManager.swift', focus: 'App entry, tab/navigation structure, routing, settings surfaces, preferences, and the runtime English/Chinese localization system (how strings are keyed and toggled).' },
  { key: 'translation-core', files: 'SwiftMandarin/Views/TranslateView.swift, SwiftMandarin/Models/TranslationState.swift, SwiftMandarin/Models/TranslationDirection.swift, SwiftMandarin/Models/TranslationHistory.swift, SwiftMandarin/Views/HistoryTabView.swift, SwiftMandarin/Services/WordTranslationService.swift', focus: 'The main translate tab: input, Apple Translation framework usage, direction handling, word-tap interactions, history recording and browsing.' },
  { key: 'text-analysis', files: 'SwiftMandarin/Services/ChineseTextAnalyzer.swift, SwiftMandarin/Services/EnglishTextAnalyzer.swift, SwiftMandarin/Services/PinyinConverter.swift, SwiftMandarin/Views/Components/RubyTextView.swift, SwiftMandarin/Views/Components/EnglishRubyTextView.swift, SwiftMandarin/Views/Components/SingleLineFit.swift', focus: 'Chinese/English segmentation, pinyin generation, tone coloring, ruby text rendering. Note exactly how words are segmented and how pinyin is displayed.' },
  { key: 'photo-ocr', files: 'SwiftMandarin/Views/PhotoTranslateView.swift, SwiftMandarin/Services/PhotoTextRecognitionService.swift, SwiftMandarin/Views/Components/CameraScannerView.swift, SwiftMandarin/Views/Components/CameraImagePicker.swift, SwiftMandarin/Services/ScreenshotStitchingService.swift, SwiftMandarin/Models/ScreenshotTranslationStore.swift, SwiftMandarin/Views/Components/TranslatedScreenshotOverlayView.swift', focus: 'Photo/camera OCR pipeline, screenshot stitching, overlay rendering, AI cleanup hook.' },
  { key: 'workbook', files: 'SwiftMandarin/Views/WorkbookGradingView.swift, SwiftMandarin/Models/WorkbookBank.swift, SwiftMandarin/Views/WorkbookQuestionBankView.swift, SwiftMandarin/Views/WorkbookGradingHistoryView.swift', focus: 'AI workbook grading: multi-image upload, vision routing, question bank, grading history.' },
  { key: 'vocab-learning', files: 'SwiftMandarin/Views/VocabularyView.swift, SwiftMandarin/Models/SavedTerm.swift, SwiftMandarin/Views/LearnView.swift, SwiftMandarin/Models/LearningCard.swift, SwiftMandarin/Models/GrammarPoint.swift, SwiftMandarin/Views/PhrasesView.swift, SwiftMandarin/Services/VocabularyImportExportService.swift, SwiftMandarin/Models/PersistentCodableStore.swift', focus: 'Saved vocabulary management, flashcard review flow, the spaced-repetition algorithm (read it carefully — exactly what algorithm is used, its parameters), grammar points, phrasebook, import/export formats.' },
  { key: 'stats-activity', files: 'SwiftMandarin/Views/StatsView.swift, SwiftMandarin/Models/LearningActivity.swift', focus: 'Activity tracking, heatmap, charts, what events are counted, what insights are shown.' },
  { key: 'ai-stack', files: 'SwiftMandarin/Services/CloudAIService.swift, SwiftMandarin/Services/OllamaService.swift, SwiftMandarin/Models/AIModelSettings.swift, SwiftMandarin/Services/AIWordExplanationService.swift, SwiftMandarin/Services/WordIdentificationService.swift, SwiftMandarin/Models/WordExplanationCacheStore.swift, SwiftMandarin/Models/BatchExplanationController.swift, SwiftMandarin/Views/Components/AIProviderConfigView.swift, SwiftMandarin/Views/Components/AIWordExplanationView.swift, SwiftMandarin/Views/Components/BatchAIAnalysisView.swift, SwiftMandarin/Services/KeychainHelper.swift, SwiftMandarin/Views/Components/ProviderIcon.swift', focus: 'The full AI provider stack: providers, request shapes, vision support, JSON handling, caching, batching, what AI features exist today and how they are invoked.' },
  { key: 'speech', files: 'SwiftMandarin/Services/SpeechService.swift, SwiftMandarin/Services/SpeechRecognitionService.swift, SwiftMandarin/Views/Components/LiveSpeechTranslationView.swift, SwiftMandarin/Services/ClipboardService.swift', focus: 'TTS voices/config, live speech recognition and translation flow, clipboard integration.' },
  { key: 'intents-project', files: 'all files under SwiftMandarin/Intents/, plus SwiftMandarin.xcodeproj/project.pbxproj (skim build settings only), any .entitlements files, and glance at SwiftMandarin/Assets.xcassets directory listing', focus: 'All App Intents / Shortcuts exposed, entitlements, deployment targets, SPM deps, what platform surfaces (widgets, watch, extensions) exist or are absent.' },
]

phase('Understand')
const maps = await parallel(SUBSYSTEMS.map(s => () => agent(
`You are studying the "${s.key}" subsystem of SwiftMandarin, a bilingual Mandarin<->English learning app for iOS 17+ and macOS (SwiftUI, ~25k lines). Repo root: ${ROOT}.

Read these files COMPLETELY: ${s.files}

Focus: ${s.focus}

Produce a precise, compact structured map. Be concrete (name types, algorithms, exact behaviors — not vague generalities). In weaknesses, include UX pain points a real user would hit, tech debt, and missing capabilities. In opportunities, list concrete improvements you noticed while reading. Your final output is consumed by another program — return only the structured data.`,
  { label: `map:${s.key}`, phase: 'Understand', schema: UNDERSTAND_SCHEMA }
)))

const map = maps.filter(Boolean)
const appMap = map.map(m =>
`## ${m.subsystem}
${m.summary}
Key types: ${m.keyTypes.map(t => `${t.name} (${t.role})`).join('; ')}
Data flow: ${m.dataFlow}
Persistence: ${m.persistence}
UX: ${m.uxDescription}
Strengths: ${m.strengths.join(' | ')}
Weaknesses: ${m.weaknesses.join(' | ')}
Opportunities noticed: ${m.opportunities.join(' | ')}`
).join('\n\n')

log(`Understanding complete: ${map.length}/10 subsystem maps built`)

const IDEA_SCHEMA = {
  type: 'object',
  properties: {
    ideas: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          category: { type: 'string' },
          description: { type: 'string', description: 'What the user sees/does; concrete behavior, <=120 words' },
          rationale: { type: 'string', description: 'Why this makes the app meaningfully better, <=60 words' },
          impact: { type: 'integer', description: '1-5, 5 = transformative for users' },
          effort: { type: 'string', enum: ['S','M','L','XL'] },
          integration: { type: 'string', description: 'Where it hooks into the existing app, <=50 words' },
        },
        required: ['title','category','description','rationale','impact','effort','integration'],
      },
    },
  },
  required: ['ideas'],
}

const LENSES = [
  { key: 'pedagogy', persona: 'a world-class language-acquisition scientist and Mandarin pedagogy expert (think: designer of FSRS, comprehensible-input research, HSK curriculum author)', focus: 'Learning effectiveness: modern spaced repetition (FSRS vs the current algorithm), sentence mining, graded readers, cloze deletion, tone-pair drills, HSK/frequency-level tagging and progression, active recall modes (typing characters, audio-first recall), interleaving, difficulty-adaptive content, measurable proficiency growth.' },
  { key: 'ux-redesign', persona: 'an elite Apple Design Award-winning product designer', focus: 'A step-change UI redesign: information architecture (is the current tab structure right?), a unifying Home/Today experience, navigation flows, onboarding for first-run, progressive disclosure, visual hierarchy, delight/animation, iPad layouts, macOS-native feel, Liquid Glass adoption, reducing taps to core actions, empty states, undo. Propose a coherent redesign vision, not just tweaks.' },
  { key: 'ai-native', persona: 'an AI-product visionary who builds AI-native consumer apps', focus: 'AI-native step changes: conversational practice partner (roleplay dialogues with voice), AI story/graded-reader generation at the user vocabulary level, personalized daily lessons generated from the user weak words, semantic vocab search, grammar correction of user-written sentences, AI-generated cloze/quiz from saved words, photo-of-homework tutoring, pronunciation feedback via AI, streaming responses. The app already has a 10-provider CloudAIService with vision + JSON mode — exploit it fully.' },
  { key: 'apple-platform', persona: 'a deep Apple-platform integration engineer', focus: 'Platform surfaces that do not exist yet: WidgetKit home/lock-screen widgets (word of the day, streak, due reviews), Live Activities, watchOS companion, Spotlight indexing of vocabulary, share extension (translate from any app), action extension, keyboard hooks, Focus filters, Handoff, iCloud/CloudKit sync across devices, App Shortcuts phrases for Siri, Vision framework upgrades, on-device Foundation Models framework, TipKit, StoreKit-free — everything native Apple.' },
  { key: 'gamification', persona: 'a motivation-design expert (Duolingo-class retention designer, but tasteful)', focus: 'Motivation loops: daily goals, streaks with freeze, XP/levels, weekly quests, milestone celebrations, review-forecast, personal records, gentle notification nudges tied to due reviews, progress toward HSK levels, share cards. Keep it tasteful for adult learners, no dark patterns.' },
  { key: 'immersion-reading', persona: 'an expert in immersion-based language learning tooling (LingQ/Pleco/DuChinese class)', focus: 'Reading & immersion: a full Reader mode for pasted/imported long text with tap-to-define and unknown-word highlighting, word-known tracking (LingQ-style), web article import, RSS/news feeds in graded Chinese, subtitle/lyrics study, clipboard-watch reading, document import (PDF/epub/txt), per-text comprehension stats, vocabulary coverage analysis of any text.' },
  { key: 'listening-speaking', persona: 'a speech-technology and pronunciation-pedagogy expert', focus: 'Listening & speaking: shadowing mode with sentence-by-sentence playback and recording, pronunciation scoring (compare user speech via SFSpeechRecognizer confidence / phoneme match), tone visualization from live pitch tracking, dictation practice mode, variable-speed TTS, listening comprehension quizzes, minimal-pair drills, per-syllable playback.' },
  { key: 'data-interop', persona: 'a power-user data and interoperability engineer', focus: 'Data: iCloud sync (CloudKit or key-value), full backup/restore, Anki .apkg export/import, Pleco XML, CSV round-trip fidelity, automatic backups, merge conflict handling, cross-device continuity, printable PDF study sheets, export of grading history, versioned data migration story, SwiftData adoption tradeoffs.' },
  { key: 'accessibility-i18n', persona: 'an accessibility and internationalization specialist', focus: 'A11y & i18n: VoiceOver audit of custom views (ruby text, heatmap, flashcards), Dynamic Type at huge sizes, Reduce Motion, color-blind-safe tone colors (current: red/green/blue/purple), traditional-character (zh-Hant) support and conversion, cangjie/zhuyin annotations, left-handed reachability, haptics, keyboard navigation on macOS/iPad.' },
  { key: 'architecture-perf', persona: 'a staff Swift architect obsessed with code health and performance', focus: 'Architecture & performance: the giant view files (1.5k lines), @Observable singletons over UserDefaults JSON vs SwiftData, actor/concurrency correctness, view-body recomputation hotspots, startup time, memory from image handling, testability (zero tests?), module boundaries, dependency injection, preview coverage, CI. Also performance features users feel: instant search over large vocab, smooth 120hz lists.' },
]

phase('Ideate')
const ideaLists = await parallel(LENSES.map(l => () => agent(
`You are ${l.persona}. You are advising a solo developer on transforming SwiftMandarin — a bilingual Mandarin<->English learning app (iOS 17+, macOS, SwiftUI) — from a good utility into a category-defining app. The owner explicitly wants a STEP CHANGE, not iterative tweaks: "think from first principles, do not be constrained by the current codebase, devise ingenious, creative, powerful, useful new features."

Here is a complete map of the current app:

${appMap}

Your lens: ${l.focus}

Generate 8-15 specific, well-thought-out ideas through this lens. Range from high-impact quick wins to ambitious flagship features. Every idea must be concretely described (what the user sees and does), justified, and rated. Avoid ideas that already exist in the app (check the map). You may also read files in ${ROOT} if you need to verify details. Return only the structured data.`,
  { label: `ideate:${l.key}`, phase: 'Ideate', schema: IDEA_SCHEMA, effort: 'high' }
)))

const allIdeas = ideaLists.filter(Boolean).flatMap((r, i) => r.ideas.map(idea => ({ ...idea, lens: LENSES[i] ? LENSES[i].key : 'unknown' })))
log(`Ideation complete: ${allIdeas.length} raw ideas from ${ideaLists.filter(Boolean).length}/10 lenses`)

phase('Synthesize')
const SYNTH_SCHEMA = {
  type: 'object',
  properties: {
    themes: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          theme: { type: 'string' },
          narrative: { type: 'string', description: 'Why this theme matters for the step change, <=80 words' },
          ideas: { type: 'array', items: { type: 'object', properties: {
            title: { type: 'string' }, description: { type: 'string' }, rationale: { type: 'string' },
            impact: { type: 'integer' }, effort: { type: 'string' }, integration: { type: 'string' },
            mergedFrom: { type: 'array', items: { type: 'string' }, description: 'titles of duplicate ideas merged into this one' },
          }, required: ['title','description','rationale','impact','effort','integration'] } },
        },
        required: ['theme','narrative','ideas'],
      },
    },
    flagshipPicks: { type: 'array', items: { type: 'string' }, description: '8-15 idea titles that together would constitute the most impressive coherent overhaul implementable in SwiftUI by a small team' },
  },
  required: ['themes','flagshipPicks'],
}

const synthesis = await agent(
`You are the chief product officer synthesizing an ideation session for SwiftMandarin (bilingual Mandarin<->English learning app). Below are ${allIdeas.length} ideas from 10 expert lenses. Deduplicate aggressively (merge near-duplicates, noting merged titles), organize into 6-10 coherent themes, keep every distinct idea (do NOT drop ideas — this must be exhaustive), refine titles/descriptions for clarity, and finally pick the flagship set: the ideas that together deliver a coherent, buildable, genuinely impressive step-change overhaul (prioritize what transforms daily use: new home experience, modern SRS, reader mode, AI conversation practice, platform widgets — judge for yourself from the data).

IDEAS (JSON):
${JSON.stringify(allIdeas, null, 1)}

Return only the structured data.`,
  { label: 'synthesize', phase: 'Synthesize', schema: SYNTH_SCHEMA, effort: 'xhigh' }
)

const critique = await agent(
`You are a completeness critic. An ideation session for SwiftMandarin (bilingual Mandarin<->English learning app, iOS/macOS SwiftUI) produced the themed idea list below. The app map is also below. Identify what is MISSING: user needs not addressed, obvious feature gaps competitors cover (Pleco, Anki, DuChinese, HelloChinese, Duolingo), platform capabilities unexploited, or weaknesses in the map that no idea addresses. Return a list of additional ideas in the same structured format (empty list if truly nothing is missing).

APP MAP:
${appMap}

THEMED IDEAS:
${JSON.stringify(synthesis && synthesis.themes ? synthesis.themes.map(t => ({ theme: t.theme, ideas: t.ideas.map(i => i.title) })) : [], null, 1)}

Return only the structured data.`,
  { label: 'completeness-critic', phase: 'Synthesize', schema: IDEA_SCHEMA, effort: 'high' }
)

return {
  subsystemMaps: map,
  synthesis,
  additionalIdeas: critique ? critique.ideas : [],
  rawIdeaCount: allIdeas.length,
}

