import SwiftUI
import AppIntents

@main
struct SwiftMandarinApp: App {
    // Shared stores for app-wide state using @Observable
    @State private var savedTermsStore = SavedTermsStore.shared
    @State private var historyStore = TranslationHistoryStore.shared
    @State private var learningStore = LearningProgressStore.shared
    @State private var activityStore = LearningActivityStore.shared
    @State private var routeStore = AppRouteStore.shared
    // Drives the in-app English ⇄ 中文 language switch. Accessing the singleton
    // here also applies the saved language to Bundle.main before the first view.
    @State private var localization = LocalizationManager.shared

    init() {
        // Ensures app shortcuts are registered and entity-backed parameters are refreshed.
        SwiftMandarinShortcutsProvider.updateAppShortcutParameters()
    }

    var body: some Scene {
        WindowGroup {
            ContentView()
                .environment(savedTermsStore)
                .environment(historyStore)
                .environment(learningStore)
                .environment(activityStore)
                .environment(routeStore)
                // Switch UI language live: format with the chosen locale and
                // rebuild the tree so every localized string re-resolves.
                .environment(\.locale, localization.locale)
                .id(localization.language)
        }

        #if os(macOS)
        Settings {
            MacOSSettingsView()
                .environment(savedTermsStore)
                .environment(historyStore)
                .environment(learningStore)
                .environment(activityStore)
                .environment(routeStore)
                .environment(\.locale, localization.locale)
                .id(localization.language)
        }
        #endif
    }
}

//
//  AppRouteStore.swift
//  SwiftMandarin
//
//  App-wide routing for App Intents and shortcuts
//

import SwiftUI
import Observation

@Observable
@MainActor
final class AppRouteStore {
    static let shared = AppRouteStore()

    var selectedTab: AppTab = .translate
    var pendingAction: AppPendingAction?

    private init() {}

    func trigger(_ kind: AppPendingAction.Kind, preferredTab: AppTab? = nil) {
        if let preferredTab {
            selectedTab = preferredTab
        }
        pendingAction = AppPendingAction(kind: kind)
    }

    func triggerReview(mode: String, source: String) {
        // On iOS the Learn screen lives inside the More hub, which pushes it
        // when this action arrives; on macOS Learn is its own sidebar item.
        #if os(iOS)
        selectedTab = .more
        #else
        selectedTab = .learn
        #endif
        pendingAction = AppPendingAction(kind: .startReview(mode: mode, source: source))
    }

    func clearPendingAction() {
        pendingAction = nil
    }
}

struct AppPendingAction: Equatable, Identifiable {
    enum Kind: Equatable {
        case openCameraScanner
        case startReview(mode: String, source: String)
        case translateScreenshots
    }

    let id: UUID = UUID()
    let kind: Kind
}

