2	//  SavedTerm.swift
3	//  SwiftMandarin
4	//
5	//  Model for saved vocabulary terms
6	//
7	
8	import Foundation
9	import SwiftUI
10	import Observation
11	
12	struct SavedTerm: Identifiable, Codable, Equatable, Hashable {
13	    let id: UUID
14	    let chinese: String
15	    let pinyin: String
16	    let definition: String
17	    let partOfSpeech: String
18	    let dateAdded: Date
19	    var sortOrder: Int
20	    var isMastered: Bool
21	    
22	    init(
23	        id: UUID = UUID(),
24	        chinese: String,
25	        pinyin: String,
26	        definition: String,
27	        partOfSpeech: String = "",
28	        dateAdded: Date = Date(),
29	        sortOrder: Int = 0,
30	        isMastered: Bool = false
31	    ) {
32	        self.id = id
33	        self.chinese = chinese
34	        self.pinyin = pinyin
35	        self.definition = definition
36	        self.partOfSpeech = partOfSpeech
37	        self.dateAdded = dateAdded
38	        self.sortOrder = sortOrder
39	        self.isMastered = isMastered
40	    }
41	
42	    private enum CodingKeys: String, CodingKey {
43	        case id, chinese, pinyin, definition, partOfSpeech, dateAdded, sortOrder, isMastered
44	    }
45	
46	    /// Tolerant decoder: a missing or malformed field falls back to a default
47	    /// rather than throwing and dropping the whole saved term.
48	    init(from decoder: Decoder) throws {
49	        let c = try decoder.container(keyedBy: CodingKeys.self)
50	        id = (try? c.decode(UUID.self, forKey: .id)) ?? UUID()
51	        chinese = (try? c.decode(String.self, forKey: .chinese)) ?? ""
52	        pinyin = (try? c.decode(String.self, forKey: .pinyin)) ?? ""
53	        definition = (try? c.decode(String.self, forKey: .definition)) ?? ""
54	        partOfSpeech = (try? c.decode(String.self, forKey: .partOfSpeech)) ?? ""
55	        dateAdded = (try? c.decode(Date.self, forKey: .dateAdded)) ?? Date()
56	        sortOrder = (try? c.decode(Int.self, forKey: .sortOrder)) ?? 0
57	        isMastered = (try? c.decode(Bool.self, forKey: .isMastered)) ?? false
58	    }
59	}
60	
61	// MARK: - Interface-language-aware display
62	
63	/// The `chinese` field is really a *headword*: photo-extraction and workbook
64	/// flows store English headwords there when the user is learning English. So
65	/// the two display sides are detected from content, and which side is the big
66	/// headline follows the interface language (= the user's native language):
67	/// 中文 UI → learning English → English is the headline, Mandarin the gloss;
68	/// English UI → learning Mandarin → Chinese headline + pinyin, English gloss.
69	extension SavedTerm {
70	
71	    /// The Chinese side of the entry (headword preferred, else definition).
72	    var chineseSide: String {
73	        if chinese.containsCJK { return chinese }
74	        if definition.containsCJK { return definition }
75	        return ""
76	    }
77	
78	    /// The English side of the entry (headword preferred, else definition).
79	    var englishSide: String {
80	        if !chinese.containsCJK, !chinese.isEmpty { return chinese }
81	        if !definition.containsCJK { return definition }
82	        return ""
83	    }
84	
85	    /// The text shown big — the side in the language the user is learning.
86	    /// Falls back to the headword when the entry has no text in that language.
87	    @MainActor
88	    var headlineText: String {
89	        let primary = LocalizationManager.shared.learningIsChinese ? chineseSide : englishSide
90	        return primary.isEmpty ? chinese : primary
91	    }
92	
93	    /// The small secondary text — the side in the user's native language.
94	    /// Empty when the entry has nothing beyond the headline.
95	    @MainActor
96	    var glossText: String {
97	        let secondary = LocalizationManager.shared.learningIsChinese ? englishSide : chineseSide
98	        return secondary == headlineText ? "" : secondary
99	    }
100	
101	    /// Pinyin is a learner aid for reading Chinese: shown only when the user
102	    /// is learning Chinese (English UI) and the entry has a Chinese side.
103	    @MainActor
104	    var showsPinyin: Bool {
105	        LocalizationManager.shared.learningIsChinese && !chineseSide.isEmpty && !pinyin.isEmpty
106	    }
107	
108	    /// Headword forms an AI explanation might be cached under. The analyzed word
109	    /// is `headlineText`, which is either side depending on the learning
110	    /// direction at generation time, so export gathers explanations matching any
111	    /// of these (deduplicated, non-empty). Non-isolated so it is usable off the
112	    /// main actor (it reads only content-derived sides, not the interface
113	    /// language).
114	    var aiCacheCandidateWords: [String] {
115	        var seen = Set<String>()
116	        var out: [String] = []
117	        for candidate in [chinese, chineseSide, englishSide] {
118	            let trimmed = candidate.trimmingCharacters(in: .whitespacesAndNewlines)
119	            guard !trimmed.isEmpty, seen.insert(trimmed).inserted else { continue }
120	            out.append(trimmed)
121	        }
122	        return out
123	    }
124	}
125	
126	// MARK: - Saved Terms Store
127	
128	@Observable
129	@MainActor
130	final class SavedTermsStore {
131	    static let shared = SavedTermsStore()
132	    
133	    var terms: [SavedTerm] = [] {
134	        didSet { save() }
135	    }
136	    
137	    /// Public accessor for saved terms (alias for terms)
138	    var savedTerms: [SavedTerm] { terms }
139	    
140	    private let saveKey = "savedTerms"
141	    
142	    private init() {
143	        load()
144	    }
145	    
146	    // MARK: - Public Methods
147	
148	    /// Normalize a term for duplicate comparison: AI/OCR sources can attach
149	    /// invisible characters (zero-width space/joiners, BOM) or stray
150	    /// whitespace, which would defeat plain string equality.
151	    private static func normalizedKey(_ s: String) -> String {
152	        String(s.unicodeScalars.filter { ![0x200B, 0x200C, 0x200D, 0xFEFF].contains($0.value) })
153	            .trimmingCharacters(in: .whitespacesAndNewlines)
154	    }
155	
156	    func add(_ term: SavedTerm) {
157	        let key = Self.normalizedKey(term.chinese)
158	        guard !terms.contains(where: { Self.normalizedKey($0.chinese) == key }) else { return }
159	        var newTerm = term
160	        newTerm.sortOrder = terms.count
161	        terms.append(newTerm)
162	        // Track activity with part of speech
163	        LearningActivityStore.shared.recordWordLearned(partOfSpeech: term.partOfSpeech)
