            .background(SMTheme.cardFill, in: RoundedRectangle(cornerRadius: SMTheme.cornerRadius, style: .continuous))
    }
}

// MARK: - Section header

/// Section title with an optional trailing "See All"-style action.
struct SMSectionHeader: View {
    let titleKey: LocalizedStringKey
    var actionKey: LocalizedStringKey? = nil
    var action: (() -> Void)? = nil

    var body: some View {
        HStack(alignment: .firstTextBaseline) {
            Text(titleKey)
                .font(.title3.weight(.semibold))
            Spacer()
            if let actionKey, let action {
                Button(action: action) {
                    Text(actionKey)
                        .font(.subheadline.weight(.medium))
                }
                .buttonStyle(.plain)
                .foregroundStyle(Color.accentColor)
            }
        }
    }
}

// MARK: - Stat tile

/// Compact metric tile: icon, big rounded number, caption.
struct StatTile: View {
    let icon: String
    let iconColor: Color
    let value: String
    let labelKey: LocalizedStringKey

    var body: some View {
        VStack(alignment: .leading, spacing: 6) {
            Image(systemName: icon)
                .font(.callout)
                .foregroundStyle(iconColor)
            Text(value)
                .font(.system(.title2, design: .rounded).weight(.bold))
                .monospacedDigit()
                .fitSingleLine()
            Text(labelKey)
                .font(.caption)
                .foregroundStyle(.secondary)
                .fitSingleLine()
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(12)
        .background(SMTheme.cardFill, in: RoundedRectangle(cornerRadius: 12, style: .continuous))
    }
}

// MARK: - Goal ring

/// Circular daily-goal progress ring with center content.
struct GoalRing: View {
    /// 0…1 (values above 1 render as a full ring).
    let progress: Double
    var lineWidth: CGFloat = 10
    var size: CGFloat = 84

    var body: some View {
        ZStack {
            Circle()
                .stroke(Color.accentColor.opacity(0.18), lineWidth: lineWidth)
            Circle()
                .trim(from: 0, to: min(max(progress, 0), 1))
                .stroke(
                    SMTheme.heroGradient,
                    style: StrokeStyle(lineWidth: lineWidth, lineCap: .round)
                )
                .rotationEffect(.degrees(-90))
                .animation(.spring(duration: 0.6), value: progress)
        }
        .frame(width: size, height: size)
    }
}

// MARK: - Streak badge

/// Flame + count, tinted by whether the streak is alive today.
struct StreakBadge: View {
    let days: Int
    let activeToday: Bool

    var body: some View {
        HStack(spacing: 5) {
            Image(systemName: "flame.fill")
