        // was a top-level tab.
        .onChange(of: routeStore.pendingAction?.id) { _, _ in
            if case .startReview = routeStore.pendingAction?.kind, path.last != .learn {
                path.append(.learn)
            }
        }
    }

    // MARK: - Sections

