phase('Find')
const results = await pipeline(
  LENSES,
  lens => agent(
`You are an adversarial code reviewer. ${CONTEXT}

YOUR LENS: ${lens.prompt}

Find REAL defects only — every finding must have a concrete failure scenario a user or the compiler would hit. Do not report style nits, hypothetical perf, or intentional design choices documented in comments. Read the actual code before claiming anything. Max 12 findings, ranked by severity. Return empty findings array if the lens is clean.`,
    { label: `find:${lens.key}`, phase: 'Find', schema: FINDINGS_SCHEMA, effort: 'high' }
  ),
  (found, lens) => {
    if (!found || !found.findings.length) return []
    log(`${lens.key}: ${found.findings.length} findings, verifying…`)
    return parallel(found.findings.map(f => () =>
      agent(
`You are a skeptical verifier. ${CONTEXT}

CLAIMED FINDING (from lens "${lens.key}"):
Title: ${f.title}
File: ${f.file} line ~${f.line} (severity ${f.severity})
Claim: ${f.description}
Suggested fix: ${f.suggestedFix}

Your job: try to REFUTE this. Read the actual code at and around the cited location plus any code it interacts with. Only confirm (isReal=true) if you can trace the concrete failure end-to-end in the real code. If the behavior is correct, intentional (check comments/handoff.md), unreachable, or already mitigated elsewhere, refute it. When uncertain, refute.`,
        { label: `verify:${f.title.slice(0,40)}`, phase: 'Verify', schema: VERDICT_SCHEMA, effort: 'high' }
      ).then(v => ({ ...f, lens: lens.key, verdict: v }))
    ))
  }
)

const all = results.filter(Boolean).flat().filter(Boolean)
const confirmed = all.filter(f => f.verdict && f.verdict.isReal)
const refuted = all.filter(f => f.verdict && !f.verdict.isReal)
log(`Review done: ${confirmed.length} confirmed, ${refuted.length} refuted`)
return { confirmed, refuted: refuted.map(f => ({ title: f.title, reasoning: f.verdict.reasoning })) }

