/// What today's session would actually contain: genuinely due reviews
/// plus new cards within the remaining daily budget. Counting the entire
/// never-reviewed backlog (thousands for a long-time user) as "due" would
/// be demoralizing rather than motivating.
private var dueCount: Int {
    let now = Date()
    var due = 0
    var newAvailable = 0
    for card in allCards {
        let progress = progressStore.getProgress(for: card.id)
        if progress.reviewCount == 0 {
            newAvailable += 1
        } else if progress.nextReviewDate <= now {
            due += 1
        }
    }
    let newBudget = max(0, progressStore.dailyNewCardLimit - progressStore.newCardsIntroducedToday)
    return due + min(newBudget, newAvailable)
}

